// Generated by vibelang from src/session/session-model-helpers.ts; the migrate flow writes it again with each batch.
export const syncPromptModel = (local, prompt) => {
    const model = local.model.current();
    if (!model)
        return;
    const next = {
        providerID: model.provider.id,
        modelID: model.id,
        variant: local.model.variant.current(),
    };
    const current = prompt.model.current();
    if (current?.providerID === next.providerID && current.modelID === next.modelID && current.variant === next.variant)
        return;
    prompt.model.set(next);
};
